use std::sync::LazyLock;

use toycomp_syntax::Lexer;

/// The lexer specification of the toy language.
///
/// The minimized DFA for this spec is generated by `build.rs` into
/// `$OUT_DIR/lexer.bin`.
pub const LEXER_STRING: &str = include_str!("../../spec/toy.lang.lex");

pub static LEXER: LazyLock<Lexer> = LazyLock::new(|| LEXER_STRING.parse().unwrap());

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn simple_lexing() {
        let lexer: Lexer = LEXER_STRING.parse().unwrap();

        let tokens = lexer.consume("fn main() {let x = -302323;}\n if x == y {let y = 0.1}");
        assert!(tokens.is_ok());
    }

    #[test]
    fn complex_lexing() {
        let lexer: Lexer = LEXER_STRING.parse().unwrap();

        let program = "fn main(x: int) -> void {
    let x = -3.0;
    let y = 1;
    let z = y - 3;
    if z == y {
        x = x - 1;
    } else {
        while true {
            return false;
        }
    }
}";
        let tokens = lexer.consume(program);
        assert!(tokens.is_ok());
    }
}
